-- chair-step: inverse of read_lane_v2_b2_07_workbench_notes — un-enrolls workbench.notes from read-lane v2 and regenerates it back to the set-form read lane.
delete from iam.read_lane_v2_rollout where token = (select token from platform.entity_types where schema_name = 'workbench' and table_name = 'notes' and is_active);
select iam.apply_rls('workbench', 'notes', (select token from platform.entity_types where schema_name = 'workbench' and table_name = 'notes' and is_active), (select rls_variant from platform.entity_types where schema_name = 'workbench' and table_name = 'notes' and is_active));
